import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uniform, uv, mix, smoothstep, vec3 } from 'three/tsl';

export default async function createNode(config, ctx) {
  const { Group, Mesh, Vector3, Color } = ctx.THREE;

  const group = new Group();
  group.position.set(2.5, -0.2, 0);
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);
    if (rimLight) {
      rimLight.removeFromParent();
    }
    if (primitiveResults.length > 0) {
      primitiveResults.forEach(r => r.cleanup?.());
    }
  };

  const primitiveResults = [];

  // Load the GLB mesh
  let gltf;
  try {
    gltf = await ctx.glbLoader.loadGLB(config.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb');
  } catch (e) {
    console.error('Failed to load GLB:', e);
    return group;
  }

  // Clone the scene to avoid mutations
  const meshScene = gltf.scene.clone();
  group.add(meshScene);

  // Apply PBR enhancement: machined-metal aesthetic
  // Iterate through all meshes and enhance materials
  meshScene.traverse((node) => {
    if (node.isMesh) {
      if (!node.material.isNodeMaterial) {
        // Convert standard material to node material for effects
        const origMat = node.material;
        const nodeMat = new MeshStandardNodeMaterial({
          color: origMat.color || new Color(0xd0d0d0),
          metalness: origMat.metalness ?? 0.5,
          roughness: origMat.roughness ?? 0.6,
          emissive: origMat.emissive || new Color(0x000000),
          emissiveIntensity: 0.1,
        });
        node.material = nodeMat;
      }
      // Enhance for machined-metal: increase metalness slightly, reduce roughness for polish
      if (node.material.metalness !== undefined) {
        node.material.metalness = Math.min(0.55, (node.material.metalness || 0.5) * 1.1);
      }
      if (node.material.roughness !== undefined) {
        node.material.roughness = Math.max(0.5, (node.material.roughness || 0.6) * 0.95);
      }
    }
  });

  // Add accent rim light (edge light effect)
  const rimLight = new ctx.THREE.PointLight(0xff2a38, 0.8, 4);
  rimLight.position.set(-0.8, 0.6, 1.2);
  group.add(rimLight);

  // Apply parallax-scroll primitive
  const parallaxResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.4,
  });
  if (parallaxResult) {
    primitiveResults.push(parallaxResult);
  }

  // Apply magnetic-cursor primitive on hover
  const magneticResult = ctx.primitives['magnetic-cursor'](group, {
    radius: 1.2,
    strength: 0.35,
  });
  if (magneticResult) {
    primitiveResults.push(magneticResult);
  }

  // Entrance animation: weighted-settle (rise-in subtle)
  gsap.from(group.position, {
    y: group.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  // Hover interaction: rise-in (subtle 0.15 units)
  group.userData.handlers = {
    onHover: () => {
      gsap.killTweensOf(group.position);
      gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.4,
        ease: 'power2.out',
      });
    },
    onHoverEnd: () => {
      gsap.killTweensOf(group.position);
      gsap.to(group.position, {
        y: -0.2,
        duration: 0.5,
        ease: 'power2.out',
      });
    },
    onClick: () => {
      // Press-down scale effect
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('navigate', { to: 'hub-journal' });
    },
  };

  return group;
}
